default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('RestrictRemoteSAM', $null, 'DoNotExpandEnvironmentNames') }
$kind = $null
if ($null -ne $current) { $kind = $key.GetValueKind('RestrictRemoteSAM') }
if (-not ($current -is [string] -and $kind -ceq 'String' -and $current -ceq 'O:BAG:BAD:(A;;RC;;;BA)')) {
    Write-Output 'Mismatch: HKLM:\SYSTEM\CurrentControlSet\Control\Lsa [RestrictRemoteSAM]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if and (ne .Vars.win25cis_system_role "domaincontroller") .Vars.win25cis_level_1 }}
  {{ if .Vars.win25cis_rule_2_3_10_11 }}
    {{ if ne .Vars.win25cis_system_role "domaincontroller" }}
registry:
  HKLM\SYSTEM\CurrentControlSet\Control\Lsa\RestrictRemoteSAM:
    title: "2.3.10.11 | Ensure 'Network access: Restrict clients allowed to make remote calls to SAM' is set to 'Administrators: Remote Access: Allow' (MS only) | RestrictRemoteSAM"
    exists: true
    value: "O:BAG:BAD:(A;;RC;;;BA)"
    type: REG_SZ
    meta:
      memberserver: 1
      server: 1
      CIS_ID:
        - 2.3.10.11
      NIST800-53R5:
        - AC-6(3)
    {{ end }}
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa')) {
    New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name 'RestrictRemoteSAM' -Value 'O:BAG:BAD:(A;;RC;;;BA)' -PropertyType String -Force | Out-Null
exit 0
